// ---------------- helpers ----------------
const money = (n) => (isFinite(n) ? n.toLocaleString("en-IN", { maximumFractionDigits: 2 }) : "0");
const num = (v) => parseFloat(v) || 0;
const uid = () => Math.random().toString(36).slice(2, 10);
const today = () => new Date().toISOString().slice(0, 10);
const fmtDate = (d) => (d ? new Date(d).toLocaleDateString("en-IN", { day: "2-digit", month: "short" }) : "—");
const SHIFT_MINUTES = 480; // standard 8-hour shift, used for efficiency & capacity calc
const SHIFT_START_HOUR = 8; // assumed shift start (24h) — only used to work out which ordinal hour "now" falls in
const ordinal = (n) => {
  const v = n % 100;
  if (v >= 11 && v <= 13) return `${n}th`;
  switch (n % 10) {
    case 1: return `${n}st`;
    case 2: return `${n}nd`;
    case 3: return `${n}rd`;
    default: return `${n}th`;
  }
};
// Hour slots as shift-relative ordinals (1st Hour, 2nd Hour...) instead of actual clock time —
// works regardless of what time the shift actually starts on a given line.
const HOURLY_SLOTS = Array.from({ length: Math.round(SHIFT_MINUTES / 60) }, (_, i) => `${ordinal(i + 1)} Hour`);
function currentHourSlotKey() {
  const h = new Date().getHours();
  const idx = h - SHIFT_START_HOUR;
  if (idx < 0 || idx >= HOURLY_SLOTS.length) return HOURLY_SLOTS[0];
  return HOURLY_SLOTS[idx];
}
const currentMonth = () => new Date().toISOString().slice(0, 7);
const fmtMonth = (m) => (m ? new Date(`${m}-01`).toLocaleDateString("en-IN", { month: "short", year: "numeric" }) : "—");
const lastNDates = (n, endDate) => {
  const out = [];
  const end = endDate ? new Date(endDate) : new Date();
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(end);
    d.setDate(d.getDate() - i);
    out.push(d.toISOString().slice(0, 10));
  }
  return out;
};
const dateRange = (start, end) => {
  let a = new Date(start || today()), b = new Date(end || today());
  if (a > b) { const tmp = a; a = b; b = tmp; }
  const out = [];
  const cur = new Date(a);
  let guard = 0;
  while (cur <= b && guard < 366) {
    out.push(cur.toISOString().slice(0, 10));
    cur.setDate(cur.getDate() + 1);
    guard++;
  }
  return out;
};
const addDays = (dateStr, n) => {
  const d = new Date(dateStr || today());
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
};

