const CPM_SCOPES = [
  { key: "sewHelper", label: "Sewing + Helper", short: "Sew+Helper" },
  { key: "sewToPack", label: "Sewing → Packing", short: "Sew→Pack" },
  { key: "cutToPack", label: "Cutting → Packing", short: "Cut→Pack" },
];
function overheadTotals(om) {
  const totalExpense = (om.expenses || []).reduce((a, e) => a + num(e.amount), 0);
  const scopes = {};
  CPM_SCOPES.forEach(({ key }) => {
    const sc = om[key] || {};
    const minutes = num(sc.manpower) * num(sc.workingDays) * num(sc.hoursPerDay) * 60;
    const cpm = minutes > 0 ? totalExpense / minutes : 0;
    scopes[key] = { minutes, cpm };
  });
  return { totalExpense, scopes };
}
function cpmFor(overheadMonths, month, scopeKey) {
  const om = (overheadMonths || []).find((o) => o.month === month);
  if (!om || !scopeKey || scopeKey === "manual") return 0;
  return overheadTotals(om).scopes[scopeKey]?.cpm || 0;
}

