function Stat({ label, value, accent, sub, big }) {
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-[10px] uppercase tracking-wider text-stone-400 font-semibold">{label}</span>
      <span className={`${big ? "text-2xl" : "text-base"} font-bold tabular-nums leading-tight ${accent || "text-stone-800"}`}>{value}</span>
      {sub && <span className="text-[11px] text-stone-400">{sub}</span>}
    </div>
  );
}

function SidebarNavGroups({ groups, menuSearch, setMenuSearch, tab, setTab, openGroups, toggleGroup, onNavigate, showSearch = true }) {
  const q = menuSearch.trim().toLowerCase();
  return (
    <>
      {showSearch && (
        <div className="px-3 pb-2">
          <div className="flex items-center gap-1.5 rounded-lg bg-teal-800/60 border border-teal-700/60 px-2.5 py-1.5">
            <Search size={13} className="text-teal-400 shrink-0" />
            <input value={menuSearch} onChange={(e) => setMenuSearch(e.target.value)} placeholder="Search menus..." className="w-full bg-transparent text-xs text-teal-50 placeholder:text-teal-400/70 outline-none" />
          </div>
        </div>
      )}
      <nav className="flex-1 overflow-y-auto px-2.5 py-2 space-y-1">
        {groups.map((g) => {
          const matchedItems = q ? g.items.filter((t) => t.label.toLowerCase().includes(q)) : g.items;
          if (q && matchedItems.length === 0) return null;
          const isOpen = q ? true : openGroups === null ? g.items.some((t) => t.key === tab) : openGroups.has(g.key);
          return (
            <div key={g.key}>
              <div className="w-full flex items-center gap-2 rounded-lg px-2.5 py-2 text-[11px] font-bold uppercase tracking-wider text-teal-300/80 hover:bg-teal-800/50 hover:text-teal-100 transition-colors">
                <g.icon size={14} className="shrink-0" />
                <span className="flex-1 text-left truncate">{g.label}</span>
                <button
                  onClick={() => toggleGroup(g.key)}
                  aria-label={`${isOpen ? "Close" : "Open"} ${g.label} menu`}
                  className="shrink-0 p-1 rounded hover:bg-teal-700/60 text-teal-300 hover:text-teal-100"
                >
                  <ChevronDown size={15} className={`transition-transform ${isOpen ? "rotate-180" : ""}`} />
                </button>
              </div>
              {isOpen && (
                <div className="ml-2 pl-3 border-l border-teal-800 space-y-0.5 mb-1">
                  {matchedItems.map((t) => (
                    <button
                      key={t.key}
                      onClick={() => { setTab(t.key); onNavigate && onNavigate(); }}
                      className={`w-full flex items-center gap-2 rounded-lg px-2.5 py-1.5 text-[13px] font-semibold transition-colors ${
                        tab === t.key ? "bg-amber-500/15 text-amber-400" : "text-teal-200/80 hover:text-teal-50 hover:bg-teal-800/50"
                      }`}
                    >
                      <t.icon size={14} className="shrink-0" />
                      <span className="truncate">{t.label}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </nav>
    </>
  );
}
